            C++

    // CPP program to copy the string
// using std::string::c_str() method
#include <bits/stdc++.h>

// Function to copy the string
const char* copyString(std::string s)
{
    const char* s2;

    // std::string::c_str() method
    s2 = s.c_str();

    return s2;
}

// Driver Code
int main()
{
    std::string s1 = "GeeksforGeeks";
    std::string s2;

    // Function Call
    s2 = copyString(s1);
    std::cout << s2;
    return 0;
}

